<template>
    <div class="d-flex">
            <h5>TYRES ASSEMBLY</h5>
        <div class="ms-auto">

        </div>
    </div>


                      <div class="panel p-0">
        <div v-if="loading" v-html="tableShimmer()"></div>
        <div v-else class="custom-table">
          <v-client-table :data="tyres" :columns="tyreColumns" :options="table_option">
            <template #status="props">
              <span 
                class="badge inv-status"
                :class="`badge-`+props.row.status.color" 
                style="cursor: pointer;"
              >
                {{ props.row.status.name }}
              </span>
            </template>

                            <template #jobcard="props">
                           <router-link :to="`/approval-chain/${props.row.jobcard}`" class="badge badge-primary">{{ props.row.jobcard }}</router-link>      
                        </template>
          </v-client-table>
        </div>
      </div>

</template>

<script setup>
import { ref, onMounted, inject ,watch } from 'vue';
import { useRoute } from 'vue-router';
    import axios from 'axios';
    import '@suadelabs/vue3-multiselect/dist/vue3-multiselect.css';
     const route = useRoute();
    const axiosInstance = axios.create({
        baseURL: process.env.VUE_APP_API_BASE_URL
    });

    const tableShimmer = inject('tableShimmer')
    const showError = inject('showError')
 const loading = ref(false);
const tyres = ref([])
const tyreColumns = ref(['Sno','jobcard','tyre_no', 'date_installed','date_removed','position','status']);

const getTyres = async() =>{
    loading.value = true
    try{
    const response = await axiosInstance.get(`asset-assemblies?asset_id=${route.params.asset_id}`)
    tyres.value = response.data.map((item,index)=>({
      ...item,
      Sno : index + 1,
       status : {
        name : item.status ==='INSTALLED' ? 'IN USE' : 'REMOVED',
        color : item.status ==='INSTALLED' ? 'success' : 'dark'
      },
      tyre_no : item.child_asset,
      date_installed : item.installed_at ?? '---',
      date_removed : item.removed_at ?? '---' ,
      jobcard : item.source_id
    }));
    }catch(error){
        console.log(error)
        showError(error.message)
    }finally{
        loading.value = false
    }
}


const props = defineProps({
    activeTab: String
});

watch(
    () => props.activeTab,
    (tab) => {
        if (tab === 'tyres') {
            getTyres();
        }
    }
);

</script>