<template>
    <div class="d-flex">
            <h5>ASSET RELATED ORDERS</h5>
        <div class="ms-auto">

        </div>
    </div>


                      <div class="panel p-0">
        <div v-if="loading" v-html="tableShimmer()"></div>
        <div v-else class="custom-table">
          <v-client-table :data="orders" :columns="orderColumns" :options="table_option">
            <template #status="props">
              <span 
                class="badge inv-status"
                :class="`badge-`+props.row.status.color" 
                style="cursor: pointer;"
              >
                {{ props.row.status.name }}
              </span>
            </template>

                            <template #lpo="props">
                           <router-link :to="`/approval-chain/${props.row.lpo}`" class="text-primary">{{ props.row.lpo }}</router-link>      
                        </template>
          </v-client-table>
        </div>
      </div>

</template>

<script setup>
import { ref, onMounted, inject ,watch } from 'vue';
import { useRoute } from 'vue-router';
    import axios from 'axios';
    import { useMeta } from '@/composables/use-meta';
    import Multiselect from '@suadelabs/vue3-multiselect';
    import '@suadelabs/vue3-multiselect/dist/vue3-multiselect.css';
     const route = useRoute();
    const axiosInstance = axios.create({
        baseURL: process.env.VUE_APP_API_BASE_URL
    });

    const tableShimmer = inject('tableShimmer')
    const showError = inject('showError')
 const loading = ref(false);
const orders = ref([])
const orderColumns = ref(['Sno','lpo', 'requester', 'date', 'project', 'description','purpose','status']);

const getOrders = async() =>{
    loading.value = true
    try{
    const response = await axiosInstance.get(`copex/report/assets/orders?asset_id=${route.params.asset_id}`)
    orders.value = response.data.map((item,index)=>({
      ...item,
      Sno : index + 1,
      lpo : item.order_id
    }));
    }catch(error){
        console.log(error)
        showError(error.message)
    }finally{
        loading.value = false
    }
}


const props = defineProps({
    activeTab: String
});

watch(
    () => props.activeTab,
    (tab) => {
        if (tab === 'orders') {
            getOrders();
        }
    }
);

</script>