<template>
   <div class="d-flex justify-content-between align-items-center my-3">
                <h4 class="mb-0">Maintenance Statement</h4>
                  <div class="d-flex align-items-center"> 
                    <span class="badge bg-light text-dark fs-6">
                    Total Cost: {{ totalMaintenanceCost }}.
                </span>
                <button class="btn btn-success ms-2" @click="printMaintenanceStatement(route.params.asset_id)">
                        <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" fill="currentColor" class="bi bi-printer" viewBox="0 0 16 16">
                            <path d="M2.5 8a.5.5 0 1 0 0-1 .5.5 0 0 0 0 1z"/>
                            <path d="M5 1a2 2 0 0 0-2 2v2H2a2 2 0 0 0-2 2v3a2 2 0 0 0 2 2h1v1a2 2 0 0 0 2 2h6a2 2 0 0 0 2-2v-1h1a2 2 0 0 0 2-2V7a2 2 0 0 0-2-2h-1V3a2 2 0 0 0-2-2H5zM4 3a1 1 0 0 1 1-1h6a1 1 0 0 1 1 1v2H4V3zm1 5a2 2 0 0 0-2 2v1H2a1 1 0 0 1-1-1V7a1 1 0 0 1 1-1h12a1 1 0 0 1 1 1v3a1 1 0 0 1-1 1h-1v-1a2 2 0 0 0-2-2H5zm7 2v3a1 1 0 0 1-1 1H5a1 1 0 0 1-1-1v-3a1 1 0 0 1 1-1h6a1 1 0 0 1 1 1z"/>
                        </svg>
                    </button>
                </div>
            </div>
            <div class="panel p-0">
        <div v-if="loading" v-html="tableShimmer()"></div>
        <div v-else class="custom-table">
          <v-client-table :data="maintenanceStatement" :columns="maintenanceColumns" :options="table_option">
            <template #jobcard="props">
              <span 
                class="badge inv-status badge-primary" 
                style="cursor: pointer;"
                @click="router.push(`/jobcard/${props.row.jobcard}/${route.params.asset_id}`)"
              >
                {{ props.row.jobcard }}
              </span>
            </template>
          </v-client-table>
        </div>
      </div>

</template>

<script setup>
import { ref, onMounted, inject ,watch } from 'vue';
import { useRoute } from 'vue-router';
    import axios from 'axios';
    import { useMeta } from '@/composables/use-meta';
    import Multiselect from '@suadelabs/vue3-multiselect';
    import '@suadelabs/vue3-multiselect/dist/vue3-multiselect.css';
    // import { useRoute, useRouter } from 'vue-router';
     const route = useRoute();
    //  const router = useRouter()
    const axiosInstance = axios.create({
        baseURL: process.env.VUE_APP_API_BASE_URL
    });
    const formatNumber = inject('formatNumber');
     const table_option = ref({
        perPage: 20,
        perPageValues: [20, 50 ,100],
        skin: 'table table-hover table-striped',
        columnsClasses: { actions: 'actions text-center' },
        sortable: ['SNo', 'name','short_name','status'],
        sortIcon: {
            base: 'sort-icon-none',
            up: 'sort-icon-asc',
            down: 'sort-icon-desc',
        },
        pagination: { nav: 'scroll', chunk: 5 },
        texts: {
            count: 'Showing {from} to {to} of {count}',
            filter: '',
            filterPlaceholder: 'Search...',
            limit: 'Results:',
        },
        resizableColumns: false,
    });

    const tableShimmer = inject('tableShimmer')
    const showError = inject('showError')
 const loading = ref(false);
const maintenanceStatement = ref([])
const totalMaintenanceCost = ref(0)
const maintenanceColumns = ref(['Sno','jobcard','date', 'description', 'beneficiary', 'rate', 'quantity', 'cost']);


const getMaintenanceStatement = async () => {
  loading.value = true
  try {
    const response = await axiosInstance.get(`asset-maintenance-statement?asset_id=${route.params.asset_id}`)
    maintenanceStatement.value = response.data.data.map((item, index) => ({
      ...item,
      Sno: index + 1,
      jobcard: item.jobcard_id,
      date: formatDate(item.created_at),
      description: item.description,
      beneficiary: item.beneficiary,
      rate: formatNumber(item.rate),
      quantity: item.quantity,
      cost: formatNumber(item.cost),
    }))
    totalMaintenanceCost.value = formatNumber(response.data.total_cost)
  } catch (error) {
    console.log(error)
    showError(error.message)
  } finally {
    loading.value = false
  }
}

const props = defineProps({
    activeTab: String
});

watch(
    () => props.activeTab,
    (tab) => {
        if (tab === 'maintenance-costs') {
            getMaintenanceStatement();
        }
    }
);

</script>