<template>
<div class="d-flex justify-content-between align-items-center my-3">
                <h4 class="mb-0">Attachments</h4>
            </div>
            <div class="panel p-0">
        <div v-if="loading" v-html="tableShimmer()"></div>
        <div v-else class="custom-table">
        <v-client-table :data="attachments" :columns="attachmentColumns" :options="table_option">
             <template
                             #actions="props" >
                                <div class="actions text-center">
                                  <a 
                  :href="`${props.row.attachment}`" 
                  target="_blank"
                  title="View Attachment"
                >
                  <svg xmlns="http://www.w3.org/2000/svg" width="26" height="26" fill="currentColor" class="bi bi-eye text-primary" viewBox="0 0 16 16" style="cursor: pointer;">
                    <path d="M16 8s-3-5.5-8-5.5S0 8 0 8s3 5.5 8 5.5S16 8 16 8M1.173 8a13 13 0 0 1 1.66-2.043C4.12 4.668 5.88 3.5 8 3.5s3.879 1.168 5.168 2.457A13 13 0 0 1 14.828 8q-.086.13-.195.288c-.335.48-.83 1.12-1.465 1.755C11.879 11.332 10.119 12.5 8 12.5s-3.879-1.168-5.168-2.457A13 13 0 0 1 1.172 8z"/>
                    <path d="M8 5.5a2.5 2.5 0 1 0 0 5 2.5 2.5 0 0 0 0-5M4.5 8a3.5 3.5 0 1 1 7 0 3.5 3.5 0 0 1-7 0"/>
                  </svg>
                </a>

                                </div>
                            </template> 
          </v-client-table>
        </div>
      </div>

</template>

<script setup>
import { ref, inject ,watch } from 'vue';
import { useRoute } from 'vue-router';
    import axios from 'axios';
    import '@suadelabs/vue3-multiselect/dist/vue3-multiselect.css';
    // import { useRoute, useRouter } from 'vue-router';
     const route = useRoute();
    //  const router = useRouter()
    const axiosInstance = axios.create({
        baseURL: process.env.VUE_APP_API_BASE_URL
    });
    const formatNumber = inject('formatNumber');
     const table_option = ref({
        perPage: 20,
        perPageValues: [20, 50 ,100],
        skin: 'table table-hover table-striped',
        columnsClasses: { actions: 'actions text-center' },
        sortable: ['SNo', 'name','short_name','status'],
        sortIcon: {
            base: 'sort-icon-none',
            up: 'sort-icon-asc',
            down: 'sort-icon-desc',
        },
        pagination: { nav: 'scroll', chunk: 5 },
        texts: {
            count: 'Showing {from} to {to} of {count}',
            filter: '',
            filterPlaceholder: 'Search...',
            limit: 'Results:',
        },
        resizableColumns: false,
    });

    const tableShimmer = inject('tableShimmer')
    const showError = inject('showError')
 const loading = ref(false);
const attachmentColumns = ref(['Sno','date','description','issuer','actions']);


const attachments = ref([]);
const getAttachments = async () => {
    loading.value = true;
    try {
        const response = await axiosInstance.get(`asset-attachments?asset_id=${route.params.asset_id}`);
        attachments.value = response.data.map((item, index) => ({
            ...item,
            Sno: index + 1,
            attachment : process.env.VUE_APP_API_BASE_URL + '../../' + item.path,  
            date: formatDate(item.date),
            issuer: item.issuer.name,
        }));
    } catch (error) {
        showError(error.message);
        console.log(error);
    }finally{
        loading.value = false; 
    }
};

const props = defineProps({
    activeTab: String
});

watch(
    () => props.activeTab,
    (tab) => {
        if (tab === 'attachments') {
            getAttachments();
        }
    }
);

</script>